  // angle: Z = (n*C + 2^(P-1)) >> P (constant multiplier)
  wire [27:0] a_prod = {19'd0, n} * 28'd524288;
  wire [27:0] a_sum  = a_prod + 28'd32768;
  wire [11:0] Z      = a_sum[27:16];
