    (cnt == 4'd1) ? 4'd2 :
    (cnt == 4'd2) ? 4'd3 :
    (cnt == 4'd3) ? 4'd4 :
    (cnt == 4'd4) ? 4'd4 :
    (cnt == 4'd5) ? 4'd5 :
    (cnt == 4'd6) ? 4'd6 :
    (cnt == 4'd7) ? 4'd7 :
    (cnt == 4'd8) ? 4'd8 :
    (cnt == 4'd9) ? 4'd9 :
    4'd10;
  assign a_cur =
    (cnt == 4'd0) ? 14'd4500 :
    (cnt == 4'd1) ? 14'd2092 :
    (cnt == 4'd2) ? 14'd1029 :
    (cnt == 4'd3) ? 14'd513 :
    (cnt == 4'd4) ? 14'd513 :
    (cnt == 4'd5) ? 14'd256 :
    (cnt == 4'd6) ? 14'd128 :
    (cnt == 4'd7) ? 14'd64 :
    (cnt == 4'd8) ? 14'd32 :
    (cnt == 4'd9) ? 14'd16 :
    14'd8;

  // one rotation: d = +1 if z >= 0; Y += d (Y >> i); z -= d A_i
  wire        d      = ~zr[13];
  wire [13:0] ysh    = Yr >> i_cur;
  wire [13:0] y_next = Yr + (ysh ^ {14{~d}}) + {13'd0, ~d};
