      busy <= 1'b0;
      done <= 1'b0;
    end else begin
      done <= busy & last;
      if (!busy) busy <= start;
      else if (last) busy <= 1'b0;
    end
  end

  always @(posedge clk) begin
    if (!busy) begin
      if (start) begin
        Yr  <= 14'd9892;
        zr  <= z_init;
        cnt <= 4'd0;
      end
    end else begin
      Yr  <= y_next;
      zr  <= z_next;
      cnt <= cnt + 4'd1;
